const wantsJson = process.argv.includes('--json');
if (wantsJson) {
  console.log(JSON.stringify({ ok: true, status: 'ready', mode: 'queue' }));
} else {
  console.log('DEVNS seed CLI ready');
}

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const outDir = path.join(process.cwd(), '.devns/artifacts/t3');
fs.mkdirSync(outDir, { recursive: true });
const cli = path.join(process.cwd(), 'src/cli.mjs');
const text = spawnSync(process.execPath, [cli, 'status'], { encoding: 'utf8' });
const json = spawnSync(process.execPath, [cli, 'status', '--json'], { encoding: 'utf8' });
let parsed = null;
try {
  parsed = JSON.parse(json.stdout);
} catch {}
const artifact = {
  projectType: 'cli',
  text: text.stdout.trim(),
  json: Boolean(parsed?.ok === true && parsed?.status === 'ready' && parsed?.mode === 'queue'),
  exitCodes: [text.status, json.status],
  attempt: process.env.DEVNS_T3_ATTEMPT
};
fs.writeFileSync(path.join(outDir, 'cli-contract.json'), JSON.stringify(artifact, null, 2) + '\n');
fs.appendFileSync(path.join(outDir, 'cli-attempts.log'), `attempt=${process.env.DEVNS_T3_ATTEMPT}\n`);
